package com.mushafi.app;
import android.app.*;import android.content.*;import android.media.*;import android.media.session.*;import android.net.Uri;import android.os.*;import org.json.*;import java.io.*;import java.util.*;

/** Full-surah playback with native verse-boundary policies, including in the background. */
public class SurahPlaybackService extends Service implements AudioManager.OnAudioFocusChangeListener {
 public static final String PLAY="surah.PLAY",PAUSE="surah.PAUSE",RESUME="surah.RESUME",STOP="surah.STOP",SKIP="surah.SKIP",SEEK="surah.SEEK",MODE="surah.MODE";
 public interface Listener{void onState(String json);}
 public class LocalBinder extends Binder{public SurahPlaybackService service(){return SurahPlaybackService.this;}}
 private final Handler handler=new Handler(Looper.getMainLooper());private final IBinder binder=new LocalBinder();private Listener listener;private MediaPlayer player;private MediaSession session;private AudioManager focus;private JSONObject catalog;private JSONArray timings;private int reader=7,chapter=1,position=0,duration=0,pendingSeek=0;private String status="stopped",message="",key="",lastNotificationKey="",seekToken="";private volatile String snapshot="{}";private boolean prepared=false,foreground=false,resumeOnGain=false;private boolean seeking=false,resumeAfterSeek=false;private int seekTarget;private long eventOrder=0;private long lastSaved=0;private android.content.BroadcastReceiver noisy;
 private final ReciterArtwork artwork=new ReciterArtwork();
 private Runnable prepareTimeout;
 private boolean randomBoundaryPending;private String playbackMode="continuous";private int anchorVerse=1;private final Random sequenceRandom=new Random();
 private final Runnable tick=new Runnable(){public void run(){if(prepared&&player!=null&&!seeking){try{position=SurahClock.logical(player.getCurrentPosition(),audioOffset());duration=effectiveDuration(player.getDuration());}catch(Exception ignored){}}if(prepared&&!seeking&&status.equals("playing")&&trimmed()&&position>=duration){finishTrack();return;}updateKey();publish();if(System.currentTimeMillis()-lastSaved>5000)persist();if(status.equals("playing")||status.equals("loading"))handler.postDelayed(this,(playbackMode.equals("single")||randomBoundaryPending||trimmed())?40:listener==null?800:240);}};
 @Override public void onCreate(){super.onCreate();focus=(AudioManager)getSystemService(AUDIO_SERVICE);try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getAssets().open("surah-audio.json")){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}catalog=new JSONObject(out.toString("UTF-8"));}catch(Exception e){catalog=new JSONObject();}
  android.content.SharedPreferences p=getSharedPreferences("surah_player",0);reader=p.getInt("reader",7);chapter=p.getInt("chapter",1);position=p.getInt("position",0);duration=p.getInt("duration",0);if(duration>0&&position>=duration-500)position=0;if(!timelineRevision().equals(p.getString("timelineRevision","")))position=0;status=position>0?"paused":"stopped";playbackMode=SurahPlaybackMode.normalize(p.getString("mode","continuous"));loadTimings();anchorVerse=verseAt(position);
  session=new MediaSession(this,"MushafiSurah");session.setFlags(MediaSession.FLAG_HANDLES_MEDIA_BUTTONS|MediaSession.FLAG_HANDLES_TRANSPORT_CONTROLS);session.setCallback(new MediaSession.Callback(){public void onPlay(){resume();}public void onPause(){pause();}public void onStop(){stop();}public void onSeekTo(long p){seek((int)Math.min(Integer.MAX_VALUE,p));}});noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(status.equals("playing")||status.equals("loading"))pause();}};if(Build.VERSION.SDK_INT>=33)registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));updateKey();publish();
 }
 private boolean valid(int r,int c){return c>=1&&c<=114&&catalog.has(String.valueOf(r))&&catalog.optJSONObject(String.valueOf(r)).optJSONObject("chapters").has(String.valueOf(c));}
 private JSONObject track()throws JSONException{return catalog.getJSONObject(String.valueOf(reader)).getJSONObject("chapters").getJSONObject(String.valueOf(chapter));}
 private void loadTimings(){try{if(!valid(reader,chapter)){reader=7;chapter=1;position=0;}timings=track().optBoolean("verseTimingVerified",true)?track().getJSONArray("timings"):new JSONArray();}catch(Exception e){timings=new JSONArray();}}
 private String readerName(){return catalog.optJSONObject(String.valueOf(reader))==null?"القارئ":catalog.optJSONObject(String.valueOf(reader)).optString("name");}
 private String chapterName(){try{return getResources().getStringArray(getResources().getIdentifier("surah_names","array",getPackageName()))[chapter-1];}catch(Exception e){return String.valueOf(chapter);}}
 private void updateKey(){key="";for(int i=0;i<timings.length();i++){JSONArray t=timings.optJSONArray(i);if(t==null)continue;if(position<t.optInt(1))break;key=chapter+":"+t.optInt(0);}}
 private void beginSeek(){if(player==null||!prepared||seeking)return;seeking=true;seekTarget=pendingSeek;handler.removeCallbacks(tick);try{if(Build.VERSION.SDK_INT>=26)player.seekTo((long)SurahClock.raw(seekTarget,audioOffset()),trimmed()?MediaPlayer.SEEK_CLOSEST:MediaPlayer.SEEK_CLOSEST_SYNC);else player.seekTo(SurahClock.raw(seekTarget,audioOffset()));publish();}catch(Exception e){seeking=false;fail("تعذر الانتقال إلى موضع التلاوة؛ أعد المحاولة.");}}
 private void completeSeek(MediaPlayer mp){if(player!=mp||!seeking)return;seeking=false;if(seekTarget!=pendingSeek){beginSeek();return;}try{position=SurahClock.logical(mp.getCurrentPosition(),audioOffset());if(resumeAfterSeek&&!status.equals("stopped")&&!status.equals("ended")){mp.start();status="playing";}resumeAfterSeek=false;updateKey();persist();updateSession();publish();handler.removeCallbacks(tick);if(status.equals("playing")||status.equals("loading"))handler.post(tick);}catch(Exception e){fail("تعذر متابعة الصوت بعد الانتقال؛ أعد المحاولة.");}}

 private void releasePlayer(){if(prepareTimeout!=null){handler.removeCallbacks(prepareTimeout);prepareTimeout=null;}handler.removeCallbacks(tick);seeking=false;resumeAfterSeek=false;prepared=false;if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}}
 private void persist(){lastSaved=System.currentTimeMillis();getSharedPreferences("surah_player",0).edit().putString("timelineRevision",timelineRevision()).putInt("reader",reader).putInt("chapter",chapter).putInt("position",position).putInt("duration",duration).putString("mode",playbackMode).apply();}
 private void updateSession(){if(session==null)return;int state=status.equals("playing")?PlaybackState.STATE_PLAYING:status.equals("loading")?PlaybackState.STATE_BUFFERING:status.equals("paused")?PlaybackState.STATE_PAUSED:status.equals("error")?PlaybackState.STATE_ERROR:PlaybackState.STATE_STOPPED;PlaybackState.Builder b=new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SEEK_TO).setState(state,position,state==PlaybackState.STATE_PLAYING?1:0);session.setPlaybackState(b.build());MediaMetadata.Builder metadata=new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,UiLocale.text(this,"سورة "+chapterName())).putString(MediaMetadata.METADATA_KEY_ARTIST,UiLocale.text(this,readerName())).putLong(MediaMetadata.METADATA_KEY_DURATION,duration);android.graphics.Bitmap cover=artwork.forReader(this,reader);if(cover!=null)metadata.putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART,cover).putBitmap(MediaMetadata.METADATA_KEY_ART,cover).putBitmap(MediaMetadata.METADATA_KEY_DISPLAY_ICON,cover);session.setMetadata(metadata.build());}
 private void publish(){eventOrder=Math.max(eventOrder+1,SystemClock.elapsedRealtimeNanos()/1000);try{snapshot=new JSONObject().put("timingAvailable",timings.length()>0).put("playbackMode",playbackMode).put("eventOrder",eventOrder).put("seeking",seeking).put("seekPosition",pendingSeek).put("seekToken",seekToken).put("reader",reader).put("chapter",chapter).put("position",position).put("duration",duration).put("status",status).put("key",key).put("message",message).toString();}catch(Exception ignored){}if(listener!=null)listener.onState(snapshot);if(foreground&&!lastNotificationKey.equals(status+key)){lastNotificationKey=status+key;((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(7800,notification());}}
 public String snapshot(){return snapshot;}
 public void attach(Listener next){listener=next;if(next!=null)next.onState(snapshot);}
 public void detach(Listener old){if(listener==old)listener=null;}
 private PendingIntent command(String action,int request){Intent i=new Intent(this,SurahPlaybackService.class).setAction(action);return Build.VERSION.SDK_INT>=26&&action.equals(RESUME)?PendingIntent.getForegroundService(this,request,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE):PendingIntent.getService(this,request,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private Notification notification(){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel("surah_playback_v1",UiLocale.text(this,"التلاوة الصوتية"),NotificationManager.IMPORTANCE_LOW);c.setSound(null,null);c.setShowBadge(false);nm.createNotificationChannel(c);}Intent open=new Intent(this,MainActivity.class).putExtra("openSurahPlayer",true).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent content=PendingIntent.getActivity(this,7801,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);boolean running=status.equals("playing")||status.equals("loading");Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"surah_playback_v1"):new Notification.Builder(this);int icon=AppIdentity.notificationIcon(this);android.graphics.Bitmap cover=artwork.forReader(this,reader);if(cover!=null)b.setLargeIcon(cover);b.setSmallIcon(icon).setColor(AppIdentity.notificationColor(this)).setContentTitle(UiLocale.text(this,"سورة "+chapterName())).setContentText(UiLocale.text(this,readerName())+(key.isEmpty()?"":" · "+UiLocale.text(this,"الآية")+" "+key.split(":")[1])).setContentIntent(content).setVisibility(Notification.VISIBILITY_PUBLIC).setOnlyAlertOnce(true).setShowWhen(false).setOngoing(running).setCategory(Notification.CATEGORY_TRANSPORT).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1));b.addAction(running?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,running?UiLocale.text(this,"إيقاف مؤقت"):UiLocale.text(this,"تشغيل"),command(running?PAUSE:RESUME,7802));b.addAction(android.R.drawable.ic_menu_close_clear_cancel,UiLocale.text(this,"إنهاء"),command(STOP,7803));b.setDeleteIntent(command(STOP,7803));return b.build();}
 private void ensureForeground(){session.setActive(true);foreground=true;lastNotificationKey="";if(Build.VERSION.SDK_INT>=29)startForeground(7800,notification(),android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(7800,notification());}
 public void play(int r,int c,int verse){randomBoundaryPending=false;resumeOnGain=false;if(!valid(r,c)){message="التلاوة غير متاحة";status="error";publish();return;}if(r==reader&&c==chapter&&prepared){if(status.equals("ended"))seek(0);if(verse>0)seekVerse(verse);resume();return;}int saved=reader==r&&chapter==c&&!status.equals("ended")?position:0;releasePlayer();reader=r;chapter=c;duration=0;position=saved;loadTimings();pendingSeek=position;if(verse>0){pendingSeek=0;for(int i=0;i<timings.length();i++){JSONArray t=timings.optJSONArray(i);if(t.optInt(0)==verse){pendingSeek=verse==1?0:t.optInt(1);break;}}}if(timings.length()==0&&verse>0)pendingSeek=0;position=pendingSeek;anchorVerse=verseAt(position);status="loading";message="";updateKey();updateSession();ensureForeground();publish();
  prepareSource();
 }
 private void prepareSource(){
  try{String source=track().getString("url");Uri uri=Uri.parse(source);if(!"https".equals(uri.getScheme())||!("download.quranicaudio.com".equals(uri.getHost())||"cdn.mp3quran.net".equals(uri.getHost())||"download.qurancomplex.gov.sa".equals(uri.getHost())))throw new IOException("audio source");if(focus.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED)throw new IOException("audio focus");final MediaPlayer next=new MediaPlayer();player=next;next.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());next.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);next.setOnSeekCompleteListener(this::completeSeek);next.setOnPreparedListener(mp->{if(player!=mp)return;if(prepareTimeout!=null){handler.removeCallbacks(prepareTimeout);prepareTimeout=null;}prepared=true;duration=effectiveDuration(mp.getDuration());int at=Math.max(0,Math.min(pendingSeek,Math.max(0,duration-500)));pendingSeek=at;if(at>0||audioOffset()>0){resumeAfterSeek=true;beginSeek();}else{mp.start();status="playing";position=0;updateKey();updateSession();handler.removeCallbacks(tick);handler.post(tick);}});next.setOnCompletionListener(mp->{if(player==mp&&!seeking)finishTrack();});next.setOnErrorListener((mp,a,b)->{if(player==mp)sourceFailed("تعذر تشغيل السورة. تحقق من الاتصال ثم اضغط تشغيل للمتابعة.");return true;});next.setOnInfoListener((mp,what,extra)->{if(player==mp&&!seeking&&!status.equals("paused")&&!status.equals("stopped")&&!status.equals("ended")&&(what==MediaPlayer.MEDIA_INFO_BUFFERING_START||what==MediaPlayer.MEDIA_INFO_BUFFERING_END)){status=what==MediaPlayer.MEDIA_INFO_BUFFERING_START?"loading":"playing";updateSession();publish();}return false;});File cached=new File(getFilesDir(),"surah-audio/"+(track().optString("sourceVersion").equals("mp3quran-primary-v1")?"mp3quran-primary-v1/":track().optString("sourceVersion").equals("kfgqpc-v1")?"kfgqpc-v1/":track().optString("sourceVersion").equals("mp3quran-nafees-v1")?"mp3quran-nafees-v1/":"")+reader+"/"+chapter+".mp3");if(cached.length()>128&&(track().optLong("byteSize",0)==0||cached.length()==track().optLong("byteSize")))next.setDataSource(cached.getAbsolutePath());else next.setDataSource(source);next.prepareAsync();prepareTimeout=()->{if(player==next&&!prepared)sourceFailed("تعذر فتح التلاوة. تحقق من اتصال الإنترنت وحاول مجددًا.");};handler.postDelayed(prepareTimeout,15000);handler.postDelayed(tick,500);
  }catch(Exception e){sourceFailed("تعذر فتح التلاوة. تحقق من اتصال الإنترنت وحاول مجددًا.");}
 }
 private void sourceFailed(String why){fail(why);}
 private String timelineRevision(){try{return reader==1005?"full-file-v2":track().optString("sourceVersion","");}catch(Exception e){return "";}}

 private int audioOffset(){try{return Math.max(0,track().optInt("audioOffsetMs",0));}catch(Exception e){return 0;}}
 private boolean trimmed(){try{return track().optBoolean("trimToTimings",false);}catch(Exception e){return false;}}
 private int effectiveDuration(int actual){if(!trimmed()||timings.length()==0)return actual;return SurahClock.duration(actual,audioOffset(),timings.optJSONArray(timings.length()-1).optInt(2,actual));}
 private void finishTrack(){if(advanceSequence(chapterCounts()[chapter-1]))return;try{if(player!=null&&player.isPlaying())player.pause();}catch(Exception ignored){}position=duration;status="ended";handler.removeCallbacks(tick);persist();updateKey();updateSession();publish();focus.abandonAudioFocus(this);stopForeground(true);foreground=false;session.setActive(false);stopSelf();}
 private int verseAt(int at){int verse=1;for(int i=0;i<timings.length();i++){JSONArray row=timings.optJSONArray(i);if(row==null||row.optInt(1)>at)break;verse=row.optInt(0,1);}return verse;}
 public void setPlaybackMode(String mode){String selected=SurahPlaybackMode.normalize(mode);randomBoundaryPending=false;playbackMode=selected;anchorVerse=verseAt(seeking?pendingSeek:position);message="";persist();publish();}
 private int[] chapterCounts(){int[] counts=new int[114];try{JSONObject tracks=catalog.getJSONObject(String.valueOf(reader)).getJSONObject("chapters");for(int i=0;i<114;i++)counts[i]=tracks.getJSONObject(String.valueOf(i+1)).optInt("verseCount",tracks.getJSONObject(String.valueOf(i+1)).getJSONArray("timings").length());}catch(Exception ignored){}return counts;}
 private boolean advanceSequence(int verse){int[] next=RecitationSequence.next(playbackMode,chapter,verse,chapterCounts(),sequenceRandom);if(next==null)return false;play(reader,next[0],next[1]);return true;}
 private void fail(String why){resumeOnGain=false;releasePlayer();status="error";message=why;persist();updateSession();publish();focus.abandonAudioFocus(this);if(foreground)stopForeground(true);foreground=false;session.setActive(false);stopSelf();}
 public void pause(){resumeOnGain=false;if(!status.equals("playing")&&!status.equals("loading"))return;pauseInternal(true);}
 private void pauseInternal(boolean abandon){resumeAfterSeek=false;if(player!=null&&prepared){try{if(!seeking)position=SurahClock.logical(player.getCurrentPosition(),audioOffset());if(player.isPlaying())player.pause();}catch(Exception ignored){}}else if(status.equals("loading"))releasePlayer();handler.removeCallbacks(tick);status="paused";persist();updateKey();updateSession();publish();if(abandon)focus.abandonAudioFocus(this);}
 public void resume(){resumeOnGain=false;message="";if(player!=null&&prepared){ensureForeground();if(focus.requestAudioFocus(this,AudioManager.STREAM_MUSIC,AudioManager.AUDIOFOCUS_GAIN)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){fail("تعذر استئناف الصوت الآن");return;}try{if(seeking){resumeAfterSeek=true;status="loading";updateSession();publish();return;}player.start();status="playing";message="";updateSession();handler.removeCallbacks(tick);handler.post(tick);}catch(Exception e){releasePlayer();play(reader,chapter,0);}}else play(reader,chapter,0);}
 public void seekVerse(int verse){if(timings.length()==0)return;if(verse==1){seek(0);return;}for(int i=0;i<timings.length();i++){JSONArray t=timings.optJSONArray(i);if(t.optInt(0)==verse){seek(t.optInt(1));break;}}}
 public void seek(int at){seek(at,"");}
 public void seek(int at,String token){seekToken=token==null?"":token;pendingSeek=Math.max(0,Math.min(at,duration>0?duration:Integer.MAX_VALUE));anchorVerse=verseAt(pendingSeek);
  if(player!=null&&prepared){if(seeking){publish();return;}resumeAfterSeek=status.equals("playing")||status.equals("loading");if(status.equals("ended"))status="paused";try{if(player.isPlaying())player.pause();}catch(Exception ignored){}if(resumeAfterSeek)status="loading";beginSeek();return;}
  position=pendingSeek;updateKey();persist();updateSession();publish();
 }


 public void stop(){resumeOnGain=false;if(prepared&&player!=null&&!seeking)try{position=SurahClock.logical(player.getCurrentPosition(),audioOffset());}catch(Exception ignored){}releasePlayer();status="stopped";message="";persist();updateSession();publish();focus.abandonAudioFocus(this);stopForeground(true);foreground=false;session.setActive(false);stopSelf();}
 @Override public void onAudioFocusChange(int change){if(change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT||change==AudioManager.AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK){resumeOnGain=resumeOnGain||status.equals("playing")||status.equals("loading");pauseInternal(false);}else if(change==AudioManager.AUDIOFOCUS_LOSS){resumeOnGain=false;pauseInternal(false);}else if(change==AudioManager.AUDIOFOCUS_GAIN&&resumeOnGain){resumeOnGain=false;resume();}}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i==null)return START_NOT_STICKY;String a=i.getAction();if(PLAY.equals(a)){if(i.hasExtra("mode"))playbackMode=SurahPlaybackMode.normalize(i.getStringExtra("mode"));play(i.getIntExtra("reader",7),i.getIntExtra("chapter",1),i.getIntExtra("verse",0));}else if(PAUSE.equals(a))pause();else if(RESUME.equals(a))resume();else if(SKIP.equals(a))seek((seeking?pendingSeek:position)+i.getIntExtra("position",0));else if(SEEK.equals(a))seek(i.getIntExtra("position",0),i.getStringExtra("seekToken"));else if(MODE.equals(a))setPlaybackMode(i.getStringExtra("mode"));else if(STOP.equals(a))stop();return START_NOT_STICKY;}
 @Override public IBinder onBind(Intent i){return binder;}
 @Override public void onDestroy(){resumeOnGain=false;listener=null;releasePlayer();focus.abandonAudioFocus(this);if(session!=null)session.release();try{unregisterReceiver(noisy);}catch(Exception ignored){}super.onDestroy();}
}
